import React from 'react';

import { useNavigate } from 'react-router-dom';

import { addArticleAsync } from '@apps/Articles/@services/articles.service';
import { IAddArticleDTO } from '@apps/Articles/@types/articles.dto.types';
import OneArticleBody from '@apps/Articles/components/OneArticleBody';
import PageHeader from '@components/PageHeader';
import { success } from '@helpers/notificationHelper';
import PohAlert from '@ui-kit/Alert';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

interface IArticleAddPageProps {}

const ArticleEditPage: React.FC<IArticleAddPageProps> = () => {
  const [data, setData] = React.useState<IAddArticleDTO>({ name: '', text: '' });
  const [saveLoading, setSaveLoading] = React.useState(false);
  const [saveErr, setSaveErr] = React.useState<Error>();

  const navigate = useNavigate();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setSaveLoading(true);

      const res = await addArticleAsync(data);
      success('Статья добавлена и открыта для редактирования');
      navigate(`/articles/${res}/edit`);
    } catch (error) {
      setSaveErr(error as Error);
    } finally {
      setSaveLoading(false);
    }
  };

  return (
    <div>
      <Breadcrumb
        data={[
          { href: '/articles', text: 'Статьи' },
          { href: `/articles/new`, text: 'Добавление статьи', active: true },
        ]}
      />
      <PohContainer>
        <form className="d-flex flex-column" style={{ gap: 12 }} onSubmit={handleSubmit}>
          <PageHeader title="Добавление статьи">
            <PohButton variant={data.name ? ButtonVariant.Primary : undefined} type="submit">
              Сохранить
            </PohButton>
          </PageHeader>
          {saveErr && <PohAlert>{saveErr.message}</PohAlert>}
          <PohInput
            required
            value={data.name}
            placeholder="Название статьи"
            onChange={(v) => setData((c) => ({ ...c, name: v }))}
            disabled={saveLoading}
          />
          <PohRow>
            <PohCol sm={6}>
              <PohInput
                disabled={saveLoading}
                placeholder="Текст в формате Markdown"
                type={InputTypes.textarea}
                onChange={async (v: string) => {
                  setData((c) => ({ ...c, text: v }));
                }}
                value={data.text}
                style={{ overflowY: 'auto', height: 600 }}
              />
            </PohCol>
            <PohCol sm={6}>
              <div style={{ overflowY: 'auto', maxHeight: 600 }}>
                <OneArticleBody text={data.text ?? ''} />
              </div>
            </PohCol>
          </PohRow>
        </form>
      </PohContainer>
    </div>
  );
};

export default ArticleEditPage;
